n=19; g=[[0]*n for _ in range(n)]
centers={(3,6):8,(4,13):4,(12,14):1,(14,3):2}
markers={(2,6),(3,5),(3,7),(3,13),(4,6),(4,12),(4,14),(5,13),(9,8),(10,7),(10,9),(11,8),(11,14),(12,13),(12,15),(13,14),(13,3),(14,2),(14,4),(15,3)}
for r,c in markers:g[r][c]=3
for (r,c),v in centers.items():g[r][c]=v
for r in range(n):
 for c in range(n):
  if g[r][c]!=0:continue
  # closest center sharing row or col
  poss=[]
  for (a,b),v in centers.items():
   if r==a:poss.append((abs(c-b),v))
   if c==b:poss.append((abs(r-a),v))
  if poss:g[r][c]=min(poss)[1]
for row in g:print('['+','.join(map(str,row))+'],')
